        normalize-issue-env) cmd_normalize_issue_env "$@" ;;
        clear-stall) cmd_clear_stall "$@" ;;
        seed-terminal-state) cmd_seed_terminal_state "$@" ;;
        lint) cmd_lint "$@" ;;
        *) usage; exit 1 ;;
    esac
}

